<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Kanban Board</title>
  <style>
    :root {
      color-scheme: light;
      --background: #f3f5f9;
      --surface: #ffffff;
      --surface-muted: #e9edf4;
      --border: #dde3ec;
      --text: #172033;
      --muted: #687386;
      --accent: #5b67f1;
      --accent-hover: #4854dc;
      --danger: #d64242;
      --shadow: 0 8px 24px rgba(24, 32, 51, 0.08);
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      background:
        radial-gradient(circle at top left, rgba(91, 103, 241, 0.09), transparent 32rem),
        var(--background);
      color: var(--text);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    button,
    input {
      font: inherit;
    }

    .app {
      width: min(1180px, calc(100% - 32px));
      margin: 0 auto;
      padding: 42px 0;
    }

    .app-header {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 24px;
      margin-bottom: 28px;
    }

    .title-group h1 {
      margin: 0;
      font-size: clamp(1.8rem, 4vw, 2.6rem);
      letter-spacing: -0.04em;
    }

    .title-group p {
      margin: 8px 0 0;
      color: var(--muted);
    }

    .add-card-form {
      display: flex;
      gap: 10px;
      width: min(100%, 460px);
    }

    #new-card {
      min-width: 0;
      flex: 1;
      padding: 12px 14px;
      border: 1px solid var(--border);
      border-radius: 10px;
      outline: none;
      background: var(--surface);
      color: var(--text);
      box-shadow: 0 2px 8px rgba(24, 32, 51, 0.04);
      transition: border-color 0.2s, box-shadow 0.2s;
    }

    #new-card:focus {
      border-color: var(--accent);
      box-shadow: 0 0 0 3px rgba(91, 103, 241, 0.14);
    }

    #add-card {
      padding: 12px 18px;
      border: 0;
      border-radius: 10px;
      background: var(--accent);
      color: #fff;
      font-weight: 700;
      cursor: pointer;
      box-shadow: 0 5px 14px rgba(91, 103, 241, 0.24);
      transition: background 0.2s, transform 0.2s;
    }

    #add-card:hover {
      background: var(--accent-hover);
      transform: translateY(-1px);
    }

    .board {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 18px;
      align-items: start;
    }

    .column {
      min-height: 430px;
      padding: 16px;
      border: 1px solid var(--border);
      border-radius: 16px;
      background: rgba(255, 255, 255, 0.68);
      box-shadow: var(--shadow);
      transition: border-color 0.2s, background 0.2s, transform 0.2s;
    }

    .column.drag-over {
      border-color: var(--accent);
      background: rgba(91, 103, 241, 0.07);
      transform: translateY(-2px);
    }

    .column-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 14px;
      padding: 2px 2px 12px;
      border-bottom: 1px solid var(--border);
    }

    .column-header h2 {
      margin: 0;
      font-size: 1rem;
      letter-spacing: -0.01em;
    }

    .count {
      display: inline-grid;
      min-width: 28px;
      height: 28px;
      padding: 0 8px;
      place-items: center;
      border-radius: 999px;
      background: var(--surface-muted);
      color: var(--muted);
      font-size: 0.82rem;
      font-weight: 800;
    }

    .card-container {
      display: flex;
      min-height: 340px;
      flex-direction: column;
      gap: 10px;
    }

    .card {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 12px;
      padding: 15px;
      border: 1px solid var(--border);
      border-radius: 12px;
      background: var(--surface);
      box-shadow: 0 4px 12px rgba(24, 32, 51, 0.06);
      cursor: grab;
      transition: box-shadow 0.2s, transform 0.2s, opacity 0.2s;
    }

    .card:hover {
      transform: translateY(-1px);
      box-shadow: 0 8px 18px rgba(24, 32, 51, 0.1);
    }

    .card.dragging {
      opacity: 0.45;
      cursor: grabbing;
    }

    .card-title {
      overflow-wrap: anywhere;
      line-height: 1.45;
    }

    .card-del {
      display: grid;
      width: 28px;
      height: 28px;
      flex: 0 0 auto;
      padding: 0;
      place-items: center;
      border: 0;
      border-radius: 8px;
      background: transparent;
      color: var(--muted);
      cursor: pointer;
      font-size: 1.15rem;
      line-height: 1;
      transition: background 0.2s, color 0.2s;
    }

    .card-del:hover {
      background: #fff0f0;
      color: var(--danger);
    }

    @media (max-width: 760px) {
      .app {
        width: min(100% - 20px, 600px);
        padding: 24px 0;
      }

      .app-header {
        align-items: stretch;
        flex-direction: column;
      }

      .add-card-form {
        width: 100%;
      }

      .board {
        grid-template-columns: 1fr;
      }

      .column {
        min-height: 220px;
      }

      .card-container {
        min-height: 130px;
      }
    }

    @media (max-width: 420px) {
      .add-card-form {
        flex-direction: column;
      }
    }
  </style>
</head>
<body>
  <main class="app">
    <header class="app-header">
      <div class="title-group">
        <h1>Kanban Board</h1>
        <p>Organize tasks and keep work moving.</p>
      </div>

      <div class="add-card-form" role="group" aria-label="Add a task">
        <input
          id="new-card"
          type="text"
          placeholder="Add a new task…"
          aria-label="New task title"
          autocomplete="off"
        >
        <button id="add-card" type="button">Add task</button>
      </div>
    </header>

    <section class="board" aria-label="Kanban board">
      <section class="column" id="col-todo" data-column="todo">
        <header class="column-header">
          <h2>To Do</h2>
          <span class="count" aria-label="0 cards">0</span>
        </header>
        <div class="card-container" aria-label="To Do cards"></div>
      </section>

      <section class="column" id="col-doing" data-column="doing">
        <header class="column-header">
          <h2>Doing</h2>
          <span class="count" aria-label="0 cards">0</span>
        </header>
        <div class="card-container" aria-label="Doing cards"></div>
      </section>

      <section class="column" id="col-done" data-column="done">
        <header class="column-header">
          <h2>Done</h2>
          <span class="count" aria-label="0 cards">0</span>
        </header>
        <div class="card-container" aria-label="Done cards"></div>
      </section>
    </section>
  </main>

  <script>
    (() => {
      "use strict";

      const STORAGE_KEY = "kanban-board-state";
      const columns = Array.from(document.querySelectorAll(".column"));
      const input = document.getElementById("new-card");
      const addButton = document.getElementById("add-card");
      let draggedCard = null;

      function makeId() {
        if (window.crypto && typeof window.crypto.randomUUID === "function") {
          return window.crypto.randomUUID();
        }
        return "card-" + Date.now() + "-" + Math.random().toString(36).slice(2);
      }

      function updateCounts() {
        columns.forEach((column) => {
          const count = column.querySelectorAll(".card").length;
          const countElement = column.querySelector(".count");
          countElement.textContent = String(count);
          countElement.setAttribute("aria-label", count + (count === 1 ? " card" : " cards"));
        });
      }

      function getBoardState() {
        const state = {};

        columns.forEach((column) => {
          state[column.dataset.column] = Array.from(
            column.querySelectorAll(".card")
          ).map((card) => ({
            id: card.dataset.id,
            title: card.querySelector(".card-title").textContent
          }));
        });

        return state;
      }

      function saveBoard() {
        try {
          localStorage.setItem(STORAGE_KEY, JSON.stringify(getBoardState()));
        } catch (error) {
          console.warn("Unable to save the board.", error);
        }
      }

      function createCard(title, id = makeId()) {
        const card = document.createElement("article");
        card.className = "card";
        card.draggable = true;
        card.setAttribute("draggable", "true");
        card.dataset.id = id;

        const titleElement = document.createElement("span");
        titleElement.className = "card-title";
        titleElement.textContent = title;

        const deleteButton = document.createElement("button");
        deleteButton.type = "button";
        deleteButton.className = "card-del";
        deleteButton.textContent = "×";
        deleteButton.setAttribute("aria-label", "Delete " + title);

        deleteButton.addEventListener("click", () => {
          if (draggedCard === card) {
            draggedCard = null;
          }
          card.remove();
          updateCounts();
          saveBoard();
        });

        card.addEventListener("dragstart", (event) => {
          draggedCard = card;
          card.classList.add("dragging");

          if (event.dataTransfer) {
            event.dataTransfer.effectAllowed = "move";
            event.dataTransfer.setData("text/plain", card.dataset.id);
          }
        });

        card.addEventListener("dragend", () => {
          card.classList.remove("dragging");
          columns.forEach((column) => column.classList.remove("drag-over"));
          draggedCard = null;
        });

        card.append(titleElement, deleteButton);
        return card;
      }

      function addCard() {
        const title = input.value.trim();

        if (!title) {
          return;
        }

        const todoContainer = document.querySelector("#col-todo .card-container");
        todoContainer.appendChild(createCard(title));
        input.value = "";
        input.focus();
        updateCounts();
        saveBoard();
      }

      function loadBoard() {
        let state = null;

        try {
          state = JSON.parse(localStorage.getItem(STORAGE_KEY));
        } catch (error) {
          console.warn("Unable to restore the board.", error);
        }

        if (!state || typeof state !== "object") {
          updateCounts();
          return;
        }

        columns.forEach((column) => {
          const container = column.querySelector(".card-container");
          const savedCards = state[column.dataset.column];

          if (!Array.isArray(savedCards)) {
            return;
          }

          savedCards.forEach((savedCard) => {
            if (
              savedCard &&
              typeof savedCard.title === "string" &&
              savedCard.title.trim()
            ) {
              container.appendChild(
                createCard(savedCard.title, savedCard.id || makeId())
              );
            }
          });
        });

        updateCounts();
      }

      columns.forEach((column) => {
        column.addEventListener("dragover", (event) => {
          event.preventDefault();
          column.classList.add("drag-over");

          if (event.dataTransfer) {
            event.dataTransfer.dropEffect = "move";
          }
        });

        column.addEventListener("dragenter", (event) => {
          event.preventDefault();
          column.classList.add("drag-over");
        });

        column.addEventListener("dragleave", (event) => {
          if (!column.contains(event.relatedTarget)) {
            column.classList.remove("drag-over");
          }
        });

        column.addEventListener("drop", (event) => {
          event.preventDefault();
          column.classList.remove("drag-over");

          let card = draggedCard;

          if (!card && event.dataTransfer) {
            const cardId = event.dataTransfer.getData("text/plain");
            if (cardId) {
              card = Array.from(document.querySelectorAll(".card")).find(
                (item) => item.dataset.id === cardId
              );
            }
          }

          if (!card) {
            return;
          }

          column.querySelector(".card-container").appendChild(card);
          card.classList.remove("dragging");
          updateCounts();
          saveBoard();
        });
      });

      addButton.addEventListener("click", addCard);

      input.addEventListener("keydown", (event) => {
        if (event.key === "Enter") {
          event.preventDefault();
          addCard();
        }
      });

      loadBoard();
    })();
  </script>
</body>
</html>
